// Initialize state and extract input
const input = $input.first().json;

const state = {
  sessionId: input.sessionId || $execution.id,
  userQuery: input.chatInput,
  history: input.history || [],
  phase: 'planning',
  plan: null,
  currentStep: 0,
  stepResults: [],
  iterations: 0,
  maxIterations: 5,
  events: [],
  startTime: Date.now()
};

// Emit RUN_STARTED event
state.events.push({
  type: 'RUN_STARTED',
  runId: $execution.id,
  threadId: state.sessionId,
  timestamp: new Date().toISOString()
});

return { json: state };

// Parse planning agent output and update state
const state = $('Initialize State').first().json;
const plannerOutput = $input.first().json.output;

try {
  // Extract JSON from the planner output
  const jsonMatch = plannerOutput.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('No JSON found in planner output');

  const plan = JSON.parse(jsonMatch[0]);
  state.plan = plan;
  state.phase = 'executing';

  // Emit STEP_STARTED for planning
  state.events.push({
    type: 'STEP_STARTED',
    stepId: 'planning',
    stepName: 'Creating execution plan',
    stepType: 'planning',
    timestamp: new Date().toISOString()
  });

  // Emit STATE_DELTA with the plan
  state.events.push({
    type: 'STATE_DELTA',
    delta: [
      { op: 'replace', path: '/phase', value: 'executing' },
      { op: 'add', path: '/plan', value: plan }
    ],
    timestamp: new Date().toISOString()
  });

  // Emit STEP_FINISHED for planning
  state.events.push({
    type: 'STEP_FINISHED',
    stepId: 'planning',
    status: 'complete',
    result: { stepsCount: plan.steps.length },
    timestamp: new Date().toISOString()
  });

} catch (error) {
  state.error = `Failed to parse plan: ${error.message}`;
  state.phase = 'error';
}

return { json: state };

// Process manager agent result and update state
const prevState = $('More Steps?').first().json;
const managerOutput = $input.first().json;

const state = { ...prevState };
const currentStep = state.plan.steps[state.currentStep];

// Record step result
const stepResult = {
  stepId: currentStep.id,
  description: currentStep.description,
  tool: currentStep.tool,
  result: managerOutput.output,
  toolCalls: managerOutput.toolCalls || [],
  completedAt: new Date().toISOString()
};

state.stepResults.push(stepResult);

// Emit TOOL_CALL events for each tool used
if (managerOutput.toolCalls) {
  for (const toolCall of managerOutput.toolCalls) {
    state.events.push({
      type: 'TOOL_CALL_START',
      toolCallId: toolCall.id || `tool_${Date.now()}`,
      toolCallName: toolCall.name,
      timestamp: new Date().toISOString()
    });

    state.events.push({
      type: 'TOOL_CALL_RESULT',
      toolCallId: toolCall.id || `tool_${Date.now()}`,
      result: JSON.stringify(toolCall.result).slice(0, 500),
      timestamp: new Date().toISOString()
    });
  }
}

// Emit STEP_FINISHED
state.events.push({
  type: 'STEP_FINISHED',
  stepId: currentStep.id,
  status: 'complete',
  result: { summary: managerOutput.output.slice(0, 200) },
  timestamp: new Date().toISOString()
});

// Move to next step
state.currentStep++;
state.iterations++;

// Emit STATE_DELTA
state.events.push({
  type: 'STATE_DELTA',
  delta: [
    { op: 'replace', path: '/plan/currentStepIndex', value: state.currentStep },
    { op: 'add', path: '/stepResults/-', value: stepResult }
  ],
  timestamp: new Date().toISOString()
});

// Emit next STEP_STARTED if more steps
if (state.currentStep < state.plan.steps.length) {
  const nextStep = state.plan.steps[state.currentStep];
  state.events.push({
    type: 'STEP_STARTED',
    stepId: nextStep.id,
    stepName: nextStep.description,
    stepType: nextStep.tool,
    timestamp: new Date().toISOString()
  });
}

return { json: state };

// Parse QC result and finalize
const state = $('More Steps?').first().json;
const qcOutput = $input.first().json.output;

try {
  const jsonMatch = qcOutput.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('No JSON in QC output');

  const qcResult = JSON.parse(jsonMatch[0]);
  state.qcResult = qcResult;
  state.phase = qcResult.approved ? 'complete' : 'revision_needed';

  // Emit QC step events
  state.events.push({
    type: 'STEP_STARTED',
    stepId: 'quality_control',
    stepName: 'Quality Control Review',
    stepType: 'review',
    timestamp: new Date().toISOString()
  });

  state.events.push({
    type: 'STEP_FINISHED',
    stepId: 'quality_control',
    status: qcResult.approved ? 'complete' : 'failed',
    result: {
      qualityScore: qcResult.qualityScore,
      approved: qcResult.approved
    },
    timestamp: new Date().toISOString()
  });

  // Emit final STATE_DELTA
  state.events.push({
    type: 'STATE_DELTA',
    delta: [
      { op: 'replace', path: '/phase', value: state.phase },
      { op: 'add', path: '/qualityScore', value: qcResult.qualityScore }
    ],
    timestamp: new Date().toISOString()
  });

} catch (error) {
  state.error = `QC parsing failed: ${error.message}`;
  state.phase = 'error';
}

return { json: state };

// Generate final response with all events
const state = $json;

// Emit RUN_FINISHED
state.events.push({
  type: 'RUN_FINISHED',
  runId: $execution.id,
  threadId: state.sessionId,
  status: state.phase === 'complete' ? 'success' : 'error',
  timestamp: new Date().toISOString()
});

// Build final output
const finalResponse = {
  output: state.qcResult?.finalSummary || 'Task completed.',
  plan: state.plan,
  stepResults: state.stepResults,
  qualityScore: state.qcResult?.qualityScore,
  iterations: state.iterations,
  events: state.events,
  executionTime: Date.now() - state.startTime
};

return { json: finalResponse };

// Reset for revision loop
const state = $json;
state.currentStep = 0;
state.stepResults = [];
state.phase = 'executing';

// Emit revision started
state.events.push({
  type: 'STEP_STARTED',
  stepId: 'revision',
  stepName: 'Executing revision based on QC feedback',
  stepType: 'revision',
  timestamp: new Date().toISOString()
});

return { json: state };
